# Generated by build.py from recipe.yml for recipe pop3-retrieve-and-delete-a-message. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'lunch.txt'), "From: ann@example.com`nTo: bob@example.com`nSubject: Lunch`n`nNoon at the usual place.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'invoice.txt'), "From: carol@example.com`nTo: bob@example.com`nSubject: Invoice 42`n`nPlease pay invoice 42.`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', 'smtp://127.0.0.1:8080/', 'pop3://127.0.0.1:8081/', 'imap://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --crlf --mail-from ann@example.com --mail-rcpt bob@example.com -T lunch.txt smtp://127.0.0.1:8080/example.com --next -o lunch.eml pop3://127.0.0.1:8081/1 --next -X "DELE 1" pop3://127.0.0.1:8081/ } finally { Stop-Process $server0 }
